import{_ as s,a0 as r,w as l,s as d,ao as a,I as n,x as e,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux 有問必答：在 Linux 上如何通過命令列來更改日期和時間 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：在 Linux 上如何通過命令列來更改日期和時間 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：在 Linux 上如何通過命令列來更改日期和時間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：在 Linux 上如何通過命令列來更改日期和時間 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141014 Linux FAQs with Answers--How to change date and time from the command line on Linux","title":"Linux 有問必答：在 Linux 上如何通過命令列來更改日期和時間","tag":"201411","desc":""},"relativePath":"201411/20141014 Linux FAQs with Answers--How to change date and time from the command line on Linux.md","filePath":"[post].md"}'),u={name:"201411/20141014 Linux FAQs with Answers--How to change date and time from the command line on Linux.md"};function m(x,t,T,L,f,g){const o=r("Link");return l(),d("div",null,[t[20]||(t[20]=a(`<h1 id="linux-有問必答-在-linux-上如何通過命令列來更改日期和時間" tabindex="-1">Linux 有問必答：在 Linux 上如何通過命令列來更改日期和時間 <a class="header-anchor" href="#linux-有問必答-在-linux-上如何通過命令列來更改日期和時間" aria-label="Permalink to “Linux 有問必答：在 Linux 上如何通過命令列來更改日期和時間”">​</a></h1><blockquote><p><strong>問題</strong>: 在 Linux 上, 我怎樣通過命令列來改變日期和時間?</p></blockquote><p>在 Linux 系統中保持日期和時間的同步是每一個 Linux 用户和系統管理員的重要責任. 很多程序都依靠精確的時間信息得以正常工作. 另外, 不精確的日期和時間會使得日誌文件中的時間戳變得毫無意義, 減弱了它們在系統檢查和檢修中的作用. 對於生產系統來説, 精確的日期和時間甚至更為重要. 例如, 在零售公司中, 所有產品必須時刻準確地計數(並儲存在資料庫服務器中)以便於財政部門計算每天及每週,每月,每年的支出和收入.</p><p>我們必須注意, 在 Linux 機器上有兩種時鐘: 由內核維持的軟件時鐘(又稱系統時鐘)和在機器關機後記錄時間的(電池供電的)硬件時鐘. 啓動的時候, 內核會把系統時鐘與硬件時鐘同步. 之後, 兩個時鐘各自獨立運行.</p><h3 id="方法一-date-命令" tabindex="-1">方法一: Date 命令 <a class="header-anchor" href="#方法一-date-命令" aria-label="Permalink to “方法一: Date 命令”">​</a></h3><p>在 Linux 中, 你可以通過 date 命令來更改系統的日期和時間:</p><pre><code># date --set=&#39;NEW_DATE&#39; 
</code></pre><p>其中 NEW_DATE 是諸如 &quot;Sun, 28 Sep 2014 16:21:42&quot; 或者 &quot;2014-09-29 16:21:42&quot; 的可讀格式的日期字符串.</p><p>日期格式也可以手動指定以獲得更精確的結果:</p><pre><code># date +FORMAT --set=&#39;NEW_DATE&#39; 
</code></pre><p>例如:</p><pre><code># date +’%Y%m%d %H%m’ --set=&#39;20140928 1518&#39; 
</code></pre><p><img src="https://farm3.staticflickr.com/2944/15220890657_858528a186_o.png" alt=""></p><p>你也可以用相對的方式地增加或減少一定的天數,週數,月數和秒數,分鐘數,小時數。 你也可以把日期和時間的參數放到一個命令中。</p><pre><code># date --set=&#39;+5 minutes&#39;
# date --set=&#39;-2 weeks&#39;
# date --set=&#39;+3 months&#39;
# date --set=&#39;-3 months +2 weeks -5 minutes&#39; 
</code></pre><p><img src="https://farm3.staticflickr.com/2943/15220655239_deba528dce_o.png" alt=""></p><p>最後, 把硬件時鐘設置為當前系統時鐘:</p><pre><code># hwclock --systohc 
</code></pre><p>運行 <strong>hwclock --systohc</strong> 的目的是將硬件時鐘同軟件時鐘同步, 這可以更正硬件時鐘的系統漂移(即時鐘按照一定的速度走快或走慢).</p><p>另一方面, 如果硬件時鐘是正確的, 但系統時鐘有誤, 可以用下面的命令更正:</p><pre><code> # hwclock --hctosys
</code></pre><p>在兩種情況下, hwclock 命令都是將兩個時鐘同步. 否則, 重啓後時間會是錯誤的, 因為當電源關閉時硬件時鐘會記憶時間. 然而, 這對於虛擬機器並不適用, 因為虛擬機器並不能訪問硬件時鐘.</p>`,22)),n("p",null,[t[1]||(t[1]=e("如果你的 Linux 系統上的默認時區是錯誤的, 你可以按照",-1)),i(o,{href:"http://ask.xmodulo.com/change-timezone-linux.html"},{default:p(()=>[...t[0]||(t[0]=[e("這個指導",-1)])]),_:1}),t[2]||(t[2]=e("進行更正.",-1))]),t[21]||(t[21]=n("h3",{id:"方法二-ntp",tabindex:"-1"},[e("方法二: NTP "),n("a",{class:"header-anchor",href:"#方法二-ntp","aria-label":"Permalink to “方法二: NTP”"},"​")],-1)),n("p",null,[t[4]||(t[4]=e("另一種使系統日期和時間保持精確的方法是使用 NTP (網絡時間協議). 在 Linux 上, ntpdate 命令通過 NTP 將系統時鐘和",-1)),i(o,{href:"http://www.pool.ntp.org/"},{default:p(()=>[...t[3]||(t[3]=[e("公共 NTP 服務器",-1)])]),_:1}),t[5]||(t[5]=e("同步.",-1))]),t[22]||(t[22]=a(`<p>你可以使用如下命令來安裝 <strong>ntpdate</strong>:</p><p>在 Debian 及基於 Debian 的發行版上:</p><pre><code># aptitude install ntpdate
</code></pre><p>在基於 Ret Hat 的發行版上:</p><pre><code># yum install ntpdate
</code></pre><p>使用 NTP 同步系統時鐘:</p><pre><code># ntpdate -u &lt;NTP 服務器名或IP&gt;
# hwclock --systohc 
</code></pre><p><img src="https://farm4.staticflickr.com/3930/15404223021_8da3b44a62_z.jpg" alt=""></p>`,8)),n("p",null,[t[7]||(t[7]=e("除了一次性使用 ntpdate 來同步時鐘, 你也可以使用 NTP 守護進程(ntpd), 它會始終在後台運行, 不斷地通過 NTP 來調整系統時鐘. 關於 NTP 的設置, 請參考",-1)),i(o,{href:"http://xmodulo.com/how-to-synchronize-time-with-ntp.html"},{default:p(()=>[...t[6]||(t[6]=[e("這個指導",-1)])]),_:1}),t[8]||(t[8]=e(".",-1))]),t[23]||(t[23]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=e("via: ",-1)),i(o,{href:"http://ask.xmodulo.com/change-date-time-command-line-linux.html"},{default:p(()=>[...t[9]||(t[9]=[e("http://ask.xmodulo.com/change-date-time-command-line-linux.html",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=e("譯者：",-1)),i(o,{href:"https://github.com/wangjiezhe"},{default:p(()=>[...t[11]||(t[11]=[e("wangjiezhe",-1)])]),_:1}),t[14]||(t[14]=e(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[12]||(t[12]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=e("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[15]||(t[15]=[e("LCTT",-1)])]),_:1}),t[18]||(t[18]=e(" 原創翻譯，",-1)),i(o,{href:"http://linux.cn/"},{default:p(()=>[...t[16]||(t[16]=[e("Linux中國",-1)])]),_:1}),t[19]||(t[19]=e(" 榮譽推出",-1))])])}const k=s(u,[["render",m]]);export{_ as __pageData,k as default};
